import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it } from "vitest";
import { Counter } from "./Counter";

describe("Counter", () => {
  it("increments when the user activates the button", async () => {
    const user = userEvent.setup();
    render(<Counter />);

    expect(screen.getByText("Count: 0")).toBeTruthy();
    await user.click(screen.getByRole("button", { name: "Increase" }));
    expect(screen.getByText("Count: 1")).toBeTruthy();
  });
});

import { expect, it } from "vitest";

const first = { id: 1, name: "Ada" };
const equivalent = { id: 1, name: "Ada" };

it("distinguishes structure from reference identity", () => {
  expect(first).toEqual(equivalent); // passes: matching object properties
  expect(first).not.toBe(equivalent); // passes: distinct object references

  const sameReference = first;
  expect(first).toBe(sameReference); // passes: same object
});

