import { afterEach, expect, it, vi } from "vitest";

const auditLog = { save: (id: number) => `saved:${id}` };

afterEach(() => {
  vi.restoreAllMocks();
});

it("controls one scenario and restores the method", () => {
  const spy = vi.spyOn(auditLog, "save").mockReturnValue("mocked");
  expect(auditLog.save(7)).toBe("mocked");
  expect(spy).toHaveBeenCalledWith(7);
});

// clearAllMocks: clear calls, keep implementation.
// resetAllMocks: clear calls and reset implementation.
// restoreAllMocks: restore original methods for spies.
// vi.stubGlobal needs its own cleanup: vi.unstubAllGlobals().

